import{_ as t,o as n,c as a,ah as o}from"./chunks/framework.ChH6X6u6.js";const u=JSON.parse('{"title":"Online payment","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/admin/paiement-en-ligne.md","filePath":"src/en/guide/admin/paiement-en-ligne.md"}'),s={name:"en/guide/admin/paiement-en-ligne.md"};function i(r,e,l,h,d,p){return n(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="online-payment" tabindex="-1">Online payment <a class="header-anchor" href="#online-payment" aria-label="Permalink to &quot;Online payment&quot;">​</a></h1><p>Online payment lets parents pay school fees from their space, by mobile money (Flooz or Mixx by Yass). Until it is switched on, parents don&#39;t see the <strong>Pay online</strong> button: they pay at the cash desk, as usual.</p><p>The page opens from <strong>Finances → Online payment</strong>. Only administrators see it.</p><h2 id="where-your-school-stands" tabindex="-1">Where your school stands <a class="header-anchor" href="#where-your-school-stands" aria-label="Permalink to &quot;Where your school stands&quot;">​</a></h2><p>The top of the page sums it up:</p><ul><li><strong>Not activated</strong>: parents cannot pay online yet;</li><li><strong>Active</strong>: the payment provider, the accepted methods, any surcharge (see below), the activation date and who set it up;</li><li><strong>Suspended</strong>: online payment was switched off, without losing its configuration. It can be switched back on at any time.</li></ul><h2 id="request-activation" tabindex="-1">Request activation <a class="header-anchor" href="#request-activation" aria-label="Permalink to &quot;Request activation&quot;">​</a></h2><p>Online payment goes through a merchant account opened in the school&#39;s name with the payment provider. edPage opens it and connects it to ERA.</p><ol><li>Fill in the <strong>Request activation</strong> form: <ul><li>the school&#39;s <strong>legal name</strong>;</li><li>the <strong>legal representative</strong>;</li><li>the <strong>RCCM</strong> (trade register) and <strong>NIF</strong> (tax number), if you have them at hand;</li><li>a contact <strong>phone</strong> and <strong>email</strong>;</li><li>the <strong>payout number for the funds</strong>, where the provider will pay the parents&#39; payments out to you;</li><li>a <strong>message</strong>, if needed.</li></ul></li><li>Click <strong>Send the request</strong>.</li></ol><p>edPage then calls you back to agree on the set-up: it is a paid service, settled directly with edPage, outside the platform. The supporting documents the provider asks for are exchanged at that point.</p><p>While it is handled, the page shows where your request stands and any note from edPage. Once the account is open, edPage switches online payment on and administrators get an email: parents see the <strong>Pay online</strong> button from that moment.</p><div class="info custom-block"><p class="custom-block-title">You don&#39;t see the form?</p><p>It disappears once online payment is active, and while a request is being handled. On a self-hosted install, it only appears if the address requests are sent to was set on the server: contact edPage directly if it was not.</p></div><h2 id="the-online-payment-surcharge" tabindex="-1">The online payment surcharge <a class="header-anchor" href="#the-online-payment-surcharge" aria-label="Permalink to &quot;The online payment surcharge&quot;">​</a></h2><p>The provider takes a commission on each transaction. To keep fees paid at the cash desk unchanged, a <strong>surcharge</strong> can apply to online payments only: with a 2.5% surcharge, a parent paying 50,000 F online is debited 51,250 F, and 50,000 F is what is credited to their fees.</p><p>The parent sees the surcharge and the total debited before confirming. The receipt shows the amount credited, the online payment fee and the total debited. Payments recorded at the cash desk never carry a surcharge.</p><p>Without a surcharge, the school builds the commission into its prices.</p><h2 id="self-hosted-install-set-it-up-yourself" tabindex="-1">Self-hosted install: set it up yourself <a class="header-anchor" href="#self-hosted-install-set-it-up-yourself" aria-label="Permalink to &quot;Self-hosted install: set it up yourself&quot;">​</a></h2><p>If your school is alone on its installation, the <strong>Configuration</strong> section lets you enter the merchant account yourself, without touching the server. These settings replace the ones in the server&#39;s configuration file.</p><ol><li>Choose the <strong>Provider</strong>.</li><li>Enter the <strong>API key</strong> the provider gave you. Once saved it is never shown again: leave the field blank to keep it, or type a new one to replace it.</li><li>Enter the <strong>Online payment surcharge</strong>, as a percentage (0 for none).</li><li>Tick <strong>Parents can pay online</strong>.</li><li>Click <strong>Save changes</strong>.</li><li>Copy the <strong>Callback address (webhook)</strong> that appears, and paste it in the provider&#39;s dashboard as the payment confirmation address. It is what turns payments from &quot;Pending&quot; to &quot;Paid&quot;. Keep it to yourself: it is secret.</li></ol><p>To suspend online payment, untick <strong>Parents can pay online</strong> and save: the configuration is kept.</p><p>Schools hosted by edPage don&#39;t have this section: edPage sets the account up for them.</p>',21)])])}const g=t(s,[["render",i]]);export{u as __pageData,g as default};
